    @Bean
    MountedApp pathlandApp2() {
        return MountedApp.of("/app2", demoApp());
    }

    private static PathlandApp demoApp() {
        return new PathlandApp() {
            @Override
            public View newRoot() {
                return new MusicPlayerView();
            }

            @Override
            public ThemeData theme() {
                return DemoTheme.adaptive();
            }
        };
    }
}

